include "Replay.dfy"

module F3_1Domain refines Domain {
  type Model = (string, map<string, string>, map<string, string>)

  datatype Action = EditEventDetails(details: map<string, string>, requirements: map<string, string>)

  ghost predicate Inv(m: Model) {
    var (event, details, requirements) := m;
    details != null && requirements != null
  }

  function Init(): Model {
    ("", map[], map[])
  }

  function Apply(m: Model, a: Action): Model {
    match a
    case EditEventDetails(details, requirements) =>
      var (event, _, _) := m;
      (event, details, requirements)
  }

  function Normalize(m: Model): Model {
    m
  }

  lemma InitSatisfiesInv()
    ensures Inv(Init())
  {
  }

  lemma StepPreservesInv(m: Model, a: Action)
    ensures Inv(Normalize(Apply(m, a)))
  {
  }

  lemma EditEventDetailsUpdates(m: Model, details: map<string, string>, requirements: map<string, string>)
    ensures Apply(m, EditEventDetails(details, requirements)) == (m.0, details, requirements)
  {
  }
}

module F3_1Kernel refines Kernel {
  import D = F3_1Domain
}

include "Replay.dfy"

module F3_2Domain refines Domain {
  type Model = (bool, map<string, string>)

  datatype Action = Login(username: string) | Register(event: string)

  ghost predicate Inv(m: Model) {
    let (authenticated, _) = m;
    authenticated ==> |m.1| > 0
  }

  function Init(): Model {
    (false, map[])
  }

  function Apply(m: Model, a: Action): Model {
    match a
    case Login(username) => (true, m.1 + [username := "authenticated"])
    case Register(event) =>
      if m.0 then
        (true, m.1)
      else
        m
  }

  function Normalize(m: Model): Model {
    m
  }

  lemma InitSatisfiesInv()
    ensures Inv(Init())
  {
  }

  lemma StepPreservesInv(m: Model, a: Action)
    ensures Inv(Normalize(Apply(m, a)))
  {
  }

  lemma RegisterWithoutAuthRedirectsToLogin(m: Model, event: string)
    requires !m.0
    ensures Apply(m, Register(event)) == m
  {
  }
}

module F3_2Kernel refines Kernel {
  import D = F3_2Domain
}
